# Downloads all portfolio photos into images\portfolio, resized to max 1000px wide.
# Run from the site folder:  powershell -ExecutionPolicy Bypass -File download_portfolio.ps1
# Instagram links expire a few days after they were generated - run this soon.
Add-Type -AssemblyName System.Drawing
New-Item -ItemType Directory -Force -Path 'images\portfolio' | Out-Null
$codec = [System.Drawing.Imaging.ImageCodecInfo]::GetImageEncoders() | Where-Object { $_.MimeType -eq 'image/jpeg' }
$ep = New-Object System.Drawing.Imaging.EncoderParameters(1)
$ep.Param[0] = New-Object System.Drawing.Imaging.EncoderParameter([System.Drawing.Imaging.Encoder]::Quality, [long]82)
$data = @'
