'@
$ok = 0; $fail = 0
foreach ($line in ($data -split "`r?`n")) {
  if (-not $line.Trim()) { continue }
  $i = $line.IndexOf('|'); $path = $line.Substring(0,$i).Replace('/','\'); $url = $line.Substring($i+1)
  try {
    $r = Invoke-WebRequest -Uri $url -UserAgent 'Mozilla/5.0' -UseBasicParsing
    $ms = New-Object System.IO.MemoryStream(,$r.Content)
    $img = [System.Drawing.Image]::FromStream($ms)
    $w = [Math]::Min(1000, $img.Width); $h = [int]($img.Height * $w / $img.Width)
    $bmp = New-Object System.Drawing.Bitmap($w, $h)
    $g = [System.Drawing.Graphics]::FromImage($bmp); $g.InterpolationMode = 'HighQualityBicubic'; $g.DrawImage($img, 0, 0, $w, $h); $g.Dispose()
    $bmp.Save((Join-Path (Get-Location) $path), $codec, $ep)
    $bmp.Dispose(); $img.Dispose(); $ms.Dispose(); $ok++
  } catch { $fail++; Write-Host "FAILED $path : $($_.Exception.Message)" }
}
Write-Host "Done. Saved $ok photos, $fail failed."
